<template>
  <view class="page">
    <view class="topbar"><text class="back" @tap="goBack">‹</text><view><text>{{ editing?'编辑套餐':'新建套餐' }}</text><text>{{ editing?'调整套餐信息与上下架状态':'创建可售卖的活动套餐' }}</text></view><view class="placeholder"/></view>
    <view class="content">
      <view class="card">
        <text class="section-title">套餐配图 <i>*</i></text><text class="section-tip">上传 1–3 张图片，首张作为封面</text>
        <view class="photos"><view v-for="(image,index) in form.images" :key="image" class="photo"><image :src="image" mode="aspectFill"/><text v-if="index===0" class="cover-tag">封面</text><text class="remove" @tap="removeImage(index)">×</text></view><view v-if="form.images.length<3" class="upload" @tap="chooseImages"><text>＋</text><text>添加图片</text></view></view>
        <view class="field"><text>套餐名称 <i>*</i></text><input v-model.trim="form.name" maxlength="30" placeholder="请输入套餐名称"/></view>
        <view class="field"><text>每日可售份数 <i>*</i></text><input v-model.number="form.dailyStock" type="number" maxlength="3" placeholder="1–999"/></view>
      </view>

      <view class="card"><view class="section-row"><view><text class="section-title">菜品配置 <i>*</i></text><text class="section-tip">至少添加一道菜品</text></view><text>{{ form.items.length }} 道</text></view><view class="dish-list"><view v-for="(dish,index) in form.items" :key="`${dish.name}-${index}`" class="dish"><view><text>{{ dish.name }}</text><text>¥{{ Number(dish.price).toFixed(2) }} / 份</text></view><view class="quantity"><text @tap="decreaseDish(index)">−</text><text>x{{ dish.quantity }}</text><text @tap="dish.quantity++">＋</text></view><text class="dish-remove" @tap="confirmRemoveDish(index)">×</text></view></view><button class="add-dish" @tap="openDish"><text>＋</text>添加菜品</button></view>

      <view class="card"><text class="section-title">价格与奖励</text><view class="price-grid"><view class="field"><text>套餐价格 <i>*</i></text><view class="money"><text>¥</text><input v-model.number="form.price" type="digit" placeholder="0.00"/></view></view><view class="field"><text>赴约人奖励 <i>*</i></text><view class="money"><input v-model.number="form.partnerRate" type="number" placeholder="0–50"/><text>%</text></view></view><view class="field"><text>平台佣金</text><view class="money readonly"><input :value="form.platformRate" disabled/><text>%</text></view></view><view class="field"><text>代理人佣金</text><view class="money readonly"><input :value="form.agentRate" disabled/><text>%</text></view></view></view>
        <view class="earnings"><view><text>菜品原价合计</text><text>¥{{ originalTotal.toFixed(2) }}</text></view><view><text>佣金与奖励合计</text><text>{{ totalRate }}%</text></view><view><text>商家单笔净收益</text><text>¥{{ netIncome.toFixed(2) }}</text></view></view>
      </view>
      <view v-if="error" class="error">! {{ error }}</view>
      <view class="bottom-actions"><button v-if="editing&&['online','reviewing'].includes(form.status)" class="outline" @tap="offline">下架</button><button class="outline" @tap="saveDraft">保存草稿</button><button class="primary" @tap="publish">{{ editing?'提交审核':'发布套餐' }}</button></view>
    </view>

    <view v-if="dishVisible" class="mask" @tap="dishVisible=false"><view class="dish-sheet" @tap.stop><view class="handle"/><view class="sheet-head"><text>添加菜品</text><text @tap="dishVisible=false">×</text></view><view class="field"><text>菜名</text><input v-model.trim="dishDraft.name" maxlength="20" placeholder="请输入菜品名称"/></view><view class="field"><text>份数</text><view class="stepper"><text @tap="dishDraft.quantity=Math.max(1,dishDraft.quantity-1)">−</text><text>{{ dishDraft.quantity }}</text><text @tap="dishDraft.quantity++">＋</text></view></view><view class="field"><text>单价</text><view class="money"><text>¥</text><input v-model.number="dishDraft.price" type="digit" placeholder="0.00"/></view></view><button class="confirm-dish" @tap="addDish">确认添加</button></view></view>
  </view>
</template>

<script setup>
import { computed, reactive, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { createCampaignDraft, useMerchantCampaigns } from '../../composables/use-merchant-campaigns'
import { enforcePortal } from '../../core/route-guard'
const {getCampaign,saveCampaign,setStatus}=useMerchantCampaigns()
const form=reactive(createCampaignDraft()),editing=ref(false),error=ref(''),dishVisible=ref(false),dishDraft=reactive({name:'',quantity:1,price:0})
const originalTotal=computed(()=>form.items.reduce((sum,item)=>sum+Number(item.price||0)*Number(item.quantity||0),0))
const totalRate=computed(()=>Number(form.platformRate||0)+Number(form.agentRate||0)+Number(form.partnerRate||0))
const netIncome=computed(()=>Math.max(0,Number(form.price||0)*(1-totalRate.value/100)))
onLoad(options=>{if(!enforcePortal('merchant'))return;if(options?.id){const value=getCampaign(options.id);if(value){Object.assign(form,JSON.parse(JSON.stringify(value)));editing.value=true}}})
function goBack(){uni.navigateBack()}
function chooseImages(){uni.chooseImage({count:3-form.images.length,sizeType:['compressed'],sourceType:['camera','album'],success:({tempFilePaths})=>form.images.push(...tempFilePaths)})}
function removeImage(index){form.images.splice(index,1)}
function openDish(){Object.assign(dishDraft,{name:'',quantity:1,price:0});dishVisible.value=true}
function addDish(){if(!dishDraft.name){uni.showToast({title:'请输入菜品名称',icon:'none'});return}if(Number(dishDraft.price)<=0){uni.showToast({title:'请输入菜品价格',icon:'none'});return}form.items.push({name:dishDraft.name,quantity:Number(dishDraft.quantity),price:Number(dishDraft.price)});dishVisible.value=false}
function decreaseDish(index){const dish=form.items[index];if(dish.quantity>1)dish.quantity--}
function confirmRemoveDish(index){uni.showModal({title:'删除菜品',content:'确认从套餐中删除此菜品吗？',confirmText:'删除',success:({confirm})=>{if(confirm)form.items.splice(index,1)}})}
function validate(){error.value='';if(form.images.length<1)error.value='请至少上传一张套餐图片';else if(!form.name||form.name.length<3)error.value='套餐名称需填写 3–30 个字符';else if(Number(form.dailyStock)<1||Number(form.dailyStock)>999)error.value='每日可售份数需为 1–999';else if(!form.items.length)error.value='请至少添加一道菜品';else if(Number(form.price)<=0)error.value='请输入正确的套餐价格';else if(Number(form.price)>originalTotal.value)error.value='套餐价格不能高于菜品原价合计';else if(Number(form.partnerRate)<0||Number(form.partnerRate)>50)error.value='赴约人奖励比例需为 0–50%';else if(totalRate.value>=100)error.value='佣金与奖励比例合计不能达到 100%';return !error.value}
function saveDraft(){if(!form.name){error.value='请至少填写套餐名称后再保存';return}form.originalPrice=originalTotal.value;const saved=saveCampaign(form);Object.assign(form,saved);uni.showToast({title:'草稿已保存',icon:'success'});setTimeout(goBack,500)}
function publish(){if(!validate()){uni.pageScrollTo({scrollTop:0,duration:250});return}form.originalPrice=originalTotal.value;const saved=saveCampaign(form,{publish:true});Object.assign(form,saved);uni.showToast({title:'已提交平台审核',icon:'success'});setTimeout(goBack,600)}
function offline(){uni.showModal({title:'确认下架',content:'下架后顾客将无法购买此套餐。',confirmText:'确认下架',success:({confirm})=>{if(!confirm)return;setStatus(form.id,'offline');uni.showToast({title:'套餐已下架',icon:'success'});setTimeout(goBack,500)}})}
</script>

<style lang="scss" scoped>
.page{min-height:100vh;background:#f4f8f6;color:#173b31}.topbar{display:flex;align-items:center;justify-content:space-between;padding:calc(30rpx + env(safe-area-inset-top)) 28rpx 21rpx;background:#fff}.back,.placeholder{width:60rpx}.back{color:#167b5e;font-size:57rpx}.topbar>view:nth-child(2){text-align:center}.topbar>view:nth-child(2) text{display:block}.topbar>view:nth-child(2) text:first-child{font-size:29rpx;font-weight:850}.topbar>view:nth-child(2) text:last-child{margin-top:5rpx;color:#96a39e;font-size:17rpx}.content{max-width:700rpx;margin:0 auto;padding:22rpx 27rpx calc(42rpx + env(safe-area-inset-bottom))}.card{margin-bottom:18rpx;padding:25rpx;border:1rpx solid #dfe7e4;border-radius:22rpx;background:#fff}.section-title,.section-tip,.field>text{display:block}.section-title{font-size:26rpx;font-weight:800}.section-title i,.field i{color:#e25b54;font-style:normal}.section-tip{margin-top:6rpx;color:#93a09b;font-size:18rpx}.photos{display:grid;grid-template-columns:repeat(3,1fr);gap:13rpx;margin:20rpx 0 25rpx}.photo,.upload{position:relative;height:150rpx;border-radius:14rpx}.photo image{width:100%;height:100%;border-radius:14rpx}.cover-tag{position:absolute;bottom:7rpx;left:7rpx;padding:5rpx 9rpx;border-radius:7rpx;background:rgba(6,91,65,.85);color:#fff;font-size:15rpx}.remove{position:absolute;top:-9rpx;right:-7rpx;display:flex;align-items:center;justify-content:center;width:34rpx;height:34rpx;border:3rpx solid #fff;border-radius:50%;background:#29453d;color:#fff}.upload{display:flex;flex-direction:column;align-items:center;justify-content:center;border:2rpx dashed #aed2c6;background:#f2faf7;color:#42816f;font-size:18rpx}.upload text:first-child{font-size:38rpx}.field{margin-top:22rpx}.field>text{margin-bottom:9rpx;color:#486159;font-size:20rpx;font-weight:700}.field input,.money{height:76rpx;border:1rpx solid #dce5e2;border-radius:13rpx;background:#fafcfb;box-sizing:border-box}.field>input{width:100%;padding:0 20rpx;font-size:23rpx}.section-row{display:flex;align-items:flex-start;justify-content:space-between}.section-row>text{padding:6rpx 12rpx;border-radius:11rpx;background:#e5f6f0;color:#16815f;font-size:18rpx}.dish-list{margin-top:17rpx}.dish{display:flex;align-items:center;gap:13rpx;margin-bottom:11rpx;padding:16rpx;border-radius:15rpx;background:#f6f9f8}.dish>view:first-child{flex:1}.dish>view:first-child text{display:block}.dish>view:first-child text:first-child{font-size:22rpx;font-weight:750}.dish>view:first-child text:last-child{margin-top:5rpx;color:#8a9994;font-size:17rpx}.quantity{display:flex;align-items:center;gap:11rpx}.quantity text:first-child,.quantity text:last-child{display:flex;align-items:center;justify-content:center;width:38rpx;height:38rpx;border-radius:11rpx;background:#e5f3ee;color:#0b8562;font-size:24rpx}.quantity text:nth-child(2){font-size:19rpx}.dish-remove{color:#d75c56;font-size:30rpx}.add-dish{margin-top:14rpx;border:1rpx dashed #79c6ae;border-radius:13rpx;background:#f1faf7;color:#117d5e;font-size:21rpx;line-height:66rpx}.add-dish::after{border:0}.add-dish text{font-size:27rpx}.price-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 17rpx}.money{display:flex;align-items:center;padding:0 16rpx}.money input{flex:1;height:70rpx;border:0;background:transparent;font-size:23rpx}.money>text{color:#60726c;font-size:21rpx}.money.readonly{background:#f1f4f3;color:#87958f}.earnings{margin-top:25rpx;padding:19rpx;border-radius:15rpx;background:#f3f8f6}.earnings>view{display:flex;justify-content:space-between;margin-bottom:12rpx;color:#63766f;font-size:20rpx}.earnings>view:last-child{margin:0;padding-top:13rpx;border-top:1rpx solid #dfe8e4;color:#173e33;font-size:23rpx;font-weight:850}.earnings>view:last-child text:last-child{color:#07805c}.error{margin-bottom:17rpx;padding:17rpx;border-radius:13rpx;background:#fff0ef;color:#c94842;font-size:20rpx}.bottom-actions{display:flex;gap:11rpx}.bottom-actions button{flex:1;border-radius:14rpx;font-size:20rpx;line-height:78rpx}.bottom-actions button::after{border:0}.outline{border:1rpx solid #c8d8d2;background:#fff;color:#4e675f}.primary{background:#078b65;color:#fff}.mask{position:fixed;z-index:50;inset:0;display:flex;align-items:flex-end;background:rgba(12,37,30,.48)}.dish-sheet{width:100%;padding:14rpx 29rpx calc(28rpx + env(safe-area-inset-bottom));border-radius:29rpx 29rpx 0 0;background:#fff;box-sizing:border-box}.handle{width:65rpx;height:7rpx;margin:0 auto 18rpx;border-radius:7rpx;background:#d7dfdc}.sheet-head{display:flex;justify-content:space-between;font-size:28rpx;font-weight:800}.sheet-head text:last-child{color:#8d9995;font-size:42rpx;font-weight:300}.stepper{display:flex;align-items:center;justify-content:space-between;height:73rpx;padding:0 18rpx;border:1rpx solid #dce5e2;border-radius:13rpx;background:#fafcfb}.stepper text:first-child,.stepper text:last-child{font-size:31rpx}.confirm-dish{margin-top:25rpx;border-radius:14rpx;background:#088d67;color:#fff;font-size:23rpx;font-weight:750;line-height:79rpx}.confirm-dish::after{border:0}
</style>
